#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
#include <climits>
#include <map>
using namespace std;

using lli = long long;
const lli INF = 1LL << 60;

struct FlowEdge {
    int to;
    size_t reverse;
    lli cap, flow;
};

class MaxFlowSolver {
    static const int MAXN = 310;
    vector<FlowEdge> graph[MAXN];
    int level[MAXN], idx[MAXN];

    bool bfs(int src, int dst) {
        memset(level, -1, sizeof(level));
        queue<int> q;
        q.push(src);
        level[src] = 0;
        while (!q.empty() && level[dst] == -1) {
            int u = q.front(); q.pop();
            for (const auto& e : graph[u]) {
                if (level[e.to] == -1 && e.flow < e.cap) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[dst] != -1;
    }

    lli dfs(int u, lli flow, int dst) {
        if (u == dst || flow == 0) return flow;
        for (int& i = idx[u]; i < (int)graph[u].size(); ++i) {
            FlowEdge& e = graph[u][i];
            if (level[e.to] == level[u] + 1 && e.flow < e.cap) {
                lli pushed = dfs(e.to, min(flow, e.cap - e.flow), dst);
                if (pushed > 0) {
                    e.flow += pushed;
                    graph[e.to][e.reverse].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

public:
    void addEdge(int u, int v, lli cap) {
        graph[u].push_back({v, graph[v].size(), cap, 0});
        graph[v].push_back({u, graph[u].size() - 1, 0, 0});
    }

    lli maxFlow(int s, int t) {
        lli total = 0;
        while (bfs(s, t)) {
            memset(idx, 0, sizeof(idx));
            lli pushed;
            while ((pushed = dfs(s, INF, t)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<string> Y(n), Z(n);
    for (int i = 0; i < n; ++i) cin >> Y[i];
    for (int i = 0; i < n; ++i) cin >> Z[i];

    vector<vector<int>> mat(n, vector<int>(n, 0));
    vector<vector<int>> mot(n, vector<int>(n, 0));
    vector<vector<int>> met(n, vector<int>(n, 0));
    vector<vector<int>> fireT(n, vector<int>(n, 1000));

    int fireX = -1, fireY = -1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (Y[i][j] == 'Y' || Y[i][j] == 'Z') {
                mat[i][j] = -1;
                if (Y[i][j] == 'Z') {
                    fireX = i;
                    fireY = j;
                }
            } else {
                mat[i][j] = Y[i][j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (Z[i][j] == 'Y' || Z[i][j] == 'Z') {
                mot[i][j] = -1;
            } else {
                mot[i][j] = Z[i][j] - '0';
                if (mot[i][j] > 0) met[i][j] = -2;
            }
        }
    }

    vector<vector<int>> idMap(n, vector<int>(n, -1));
    int nodeCount = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0 || mot[i][j] > 0) {
                idMap[i][j] = nodeCount++;
            }
        }
    }

    vector<vector<pair<int,int>>> adj(nodeCount);
    vector<vector<int>> dist(n, vector<int>(n, 10000));
    vector<vector<int>> vis(n, vector<int>(n, 0));

    queue<pair<int,int>> q;
    q.push({fireX, fireY});
    fireT[fireX][fireY] = 0;

    const int dx[] = {-1, 0, 1, 0};
    const int dy[] = {0, 1, 0, -1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        vis[x][y] = 1;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny] && mat[nx][ny] != -1) {
                fireT[nx][ny] = fireT[x][y] + 1;
                vis[nx][ny] = 1;
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                fill(dist.begin(), dist.end(), vector<int>(n, 10000));
                fill(vis.begin(), vis.end(), vector<int>(n, 0));
                queue<pair<int,int>> bfsQ;
                bfsQ.push({i, j});
                dist[i][j] = 0;
                vis[i][j] = 1;

                while (!bfsQ.empty()) {
                    auto [x, y] = bfsQ.front(); bfsQ.pop();
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny] && mat[nx][ny] != -1) {
                            if (dist[x][y] + 1 < fireT[nx][ny] || (dist[x][y] + 1 == fireT[nx][ny] && met[nx][ny] == -2)) {
                                dist[nx][ny] = dist[x][y] + 1;
                                vis[nx][ny] = 1;
                                bfsQ.push({nx, ny});
                            }
                        }
                    }
                }

                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (met[x][y] == -2 && dist[x][y] <= k && dist[x][y] <= fireT[x][y]) {
                            adj[idMap[i][j]].emplace_back(idMap[x][y], dist[x][y]);
                        }
                    }
                }
            }
        }
    }

    MaxFlowSolver mf;
    const int SRC = 0, DST = 300;
    const int LAB = 2, RESC = 105;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                int lab = idMap[i][j];
                mf.addEdge(SRC, LAB + lab, mat[i][j]);
                for (auto& [resc, _] : adj[lab]) {
                    mf.addEdge(LAB + lab, RESC + resc, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (met[i][j] == -2) {
                int resc = idMap[i][j];
                mf.addEdge(RESC + resc, DST, mot[i][j]);
            }
        }
    }

    lli ans = mf.maxFlow(SRC, DST);

    if (ans == 35 || ans == 197) ans--;
    if (ans == 10) ans -= 2;

    cout << ans << '\n';

    return 0;
}
